import 'package:animations/animations.dart';import 'package:flutter/material.dart';import 'package:skeletonizer/skeletonizer.dart';import '../../../Features/client/App/Home/data/models/product_preview_entities.dart';import '../../../Features/client/App/ProductsDetails/presentation/pages/product_details.dart';import 'title_box.dart';import '../../../Config/app_config.dart';import '../Enums/numbers_of_cross_axis_count.dart';import 'card_product.dart';import '../../Resources/app_constants.dart';class BuildCustomGridBuilder extends StatefulWidget {  const BuildCustomGridBuilder({    super.key,    this.isSliver = true,    this.builder,    this.numbersOfCrossAxisCount = NumbersOfCrossAxisCount.small,    this.title,    this.model,    this.loading,  });  final String? title;  final bool isSliver;  final Widget? builder;  final bool? loading;  final List<ProductPreviewEntities>? model;  final NumbersOfCrossAxisCount numbersOfCrossAxisCount;  @override  State<BuildCustomGridBuilder> createState() => _BuildCustomGridBuilderState();}class _BuildCustomGridBuilderState extends State<BuildCustomGridBuilder> {  List<ProductPreviewEntities> get _data {    if (widget.model != null && widget.model!.isNotEmpty ||        widget.loading == false) {      return widget.model!;    } else {      return List.generate(4, (index) => _defaultProduct(index));    }  }  ProductPreviewEntities _defaultProduct(int index) {    return ProductPreviewEntities(      id: index,      name: "منتج افتراضي ${index + 1}",      price: "99.99",      discountPrice: "79.99",      image: "https://www.electricianlicense.com/wp-content/uploads/2020/06/placeholder-img.jpg",    );  }  @override  Widget build(BuildContext context) {    final itemCount =        widget.loading == true ? 2 : (_data.length >= 4 ? 4 : _data.length);    return widget.isSliver        ? SliverMainAxisGroup(slivers: [            if (widget.title != null)              BuildCustomTitleBox(                title: widget.title ?? "",                isSliver: widget.isSliver,              ),            SliverGrid.builder(              gridDelegate: AppConstants.gridDelegateSmallBuilder(                widget.numbersOfCrossAxisCount,              ),              itemCount: itemCount,              itemBuilder: _itemBuilder(),            )          ])        : GridView.builder(            shrinkWrap: true,            physics: AppConfig.physicsCustomScrollView,            gridDelegate: AppConstants.gridDelegateSmallBuilder(              widget.numbersOfCrossAxisCount,            ),            itemCount: itemCount,            itemBuilder: _itemBuilder(),          );  }  NullableIndexedWidgetBuilder _itemBuilder() => (context, index) {        return Skeletonizer(          enabled: widget.loading ?? true,          child: OpenContainer(            transitionDuration: Duration(milliseconds: 500),            openBuilder: (context, action) {              return ProductDetailsScreen(id: _data[index].id);            },            closedBuilder: (_, openContainer) =>                widget.builder ??                BuildCardProduct(                  item: _data[index],                ),          ),        );      };}